styles.css:
html,body{overflow-x:clip}
body{-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
figure.wp-block-image{margin-left:0;margin-right:0;margin-bottom:0}
.wp-block-image img{display:block;width:100%}
.br-section{padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80)}
.br-section--tight{padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--70)}
.br-hero{padding-top:var(--wp--preset--spacing--60)}
.br-page-head{padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--30)}
.br-split{gap:var(--wp--preset--spacing--70)}
.br-projects,.br-steps,.br-stats,.br-team,.br-meta{gap:var(--wp--preset--spacing--50)}
.br-projects+.br-projects{margin-top:var(--wp--preset--spacing--60)!important}
.br-head>*{max-width:820px}
.br-narrow{max-width:900px;margin-left:auto!important;margin-right:auto!important}
.br-center{text-align:center}
.br-label{font-size:.8rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--wp--preset--color--accent);margin-bottom:.9rem}
.has-fond-color .br-label{color:var(--wp--preset--color--surface)}
.br-lead{font-size:var(--wp--preset--font-size--large);line-height:1.55;color:var(--wp--preset--color--texte-doux);max-width:34em}
.has-fond-color .br-lead{color:inherit;opacity:.85}
.br-muted{color:var(--wp--preset--color--texte-doux)}
.br-chips{gap:.5rem!important;margin-bottom:1.75rem}
.br-chip{margin:0!important;font-size:.82rem;font-weight:500;line-height:1;padding:.55rem 1rem;border-radius:var(--wp--custom--rayon--bouton);background:var(--wp--preset--color--surface);color:var(--wp--preset--color--texte)}
.br-project .br-chips{margin:1.25rem 0 .75rem}
.br-project .br-chip{background:transparent;border:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 22%,transparent);padding:.45rem .85rem}
.br-project h3{font-size:var(--wp--preset--font-size--x-large);margin:0 0 .35rem}
.br-project h3 a{text-decoration:none;color:inherit}
.br-project h3 a::after{content:" ↗";color:var(--wp--preset--color--accent)}
.br-project .wp-block-image{overflow:hidden;border-radius:var(--wp--custom--rayon--grand)}
.br-project .wp-block-image img{transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.br-project:hover .wp-block-image img{transform:scale(1.035)}
.wp-block-image.is-style-br-arrondi img{border-radius:var(--wp--custom--rayon--grand)}
.wp-block-image.is-style-br-galet img{border-radius:var(--wp--custom--forme--blob)}
.br-statement{font-family:var(--wp--preset--font-family--titres);font-size:var(--wp--preset--font-size--x-large);line-height:1.3;letter-spacing:-.01em;font-weight:500}
.br-arrow a{display:inline-block;font-weight:600;text-decoration:none;color:var(--wp--preset--color--texte);border-bottom:2px solid var(--wp--preset--color--accent);padding-bottom:.15rem}
.br-arrow a::after{content:" →";display:inline-block;transition:transform .25s}
.br-arrow a:hover::after{transform:translateX(4px)}
.br-section-head{gap:1rem 2rem}
.br-section-head h2{margin:0}
.br-section-head .br-arrow{margin:0}
.br-num{font-family:var(--wp--preset--font-family--titres);font-weight:600;font-size:1rem;width:3rem;height:3rem;display:flex;align-items:center;justify-content:center;border-radius:var(--wp--custom--forme--blob);background:var(--wp--preset--color--accent);color:var(--wp--preset--color--fond);margin-bottom:1.1rem}
.br-expertise{padding:1.75rem 0;border-top:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent)}
.br-expertise:last-child{border-bottom:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent)}
.br-expertise .br-num{float:left;margin:0 1.5rem 1rem 0}
.br-expertise h3{margin:0 0 .4rem}
.br-expertise p.br-muted{margin:0;overflow:hidden}
.br-quote{font-family:var(--wp--preset--font-family--titres);font-size:var(--wp--preset--font-size--x-large);line-height:1.3;font-weight:500;letter-spacing:-.01em}
.br-stat{font-family:var(--wp--preset--font-family--titres);font-size:clamp(3rem,6vw,4.5rem);font-weight:600;line-height:1;letter-spacing:-.03em;color:var(--wp--preset--color--secondaire);margin-bottom:.5rem}
.br-meta{border-top:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent);border-bottom:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent);padding:1.5rem 0}
.br-meta p{margin:0}
.br-meta .br-label{margin-bottom:.35rem}
.br-member h3{margin:1.5rem 0 .2rem}
.br-member p{margin:0}
.br-card{background:var(--wp--preset--color--clair);border-radius:var(--wp--custom--rayon--grand);padding:2.5rem}
.br-info+.br-info{margin-top:1.5rem}
.br-info p{margin:0}
.br-info .br-label{margin-bottom:.3rem}
.is-style-br-tirets{list-style:none;padding-left:0}
.is-style-br-tirets li{padding:.7rem 0 .7rem 2rem;border-bottom:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 12%,transparent);position:relative;margin:0}
.is-style-br-tirets li::before{content:"";position:absolute;left:0;top:1.15rem;width:.85rem;height:.6rem;background:var(--wp--preset--color--deco);border-radius:var(--wp--custom--forme--blob)}
.br-cta{position:relative;overflow:hidden}
.br-cta::before,.br-cta::after{content:"";position:absolute;border-radius:var(--wp--custom--forme--blob);pointer-events:none}
.br-cta::before{width:420px;height:300px;right:-90px;top:-80px;background:var(--wp--preset--color--deco);opacity:.9;transform:rotate(-18deg)}
.br-cta::after{width:260px;height:190px;right:180px;bottom:-110px;background:var(--wp--preset--color--surface);opacity:.35;transform:rotate(12deg)}
.br-cta-inner{position:relative;z-index:1}
.br-cta-inner>*{max-width:680px}
.br-cta h2{font-size:var(--wp--preset--font-size--xx-large);color:inherit}
.br-cta .wp-block-button__link:hover{background:var(--wp--preset--color--accent)!important;color:var(--wp--preset--color--fond)!important}
.br-posts .wp-block-post-template{gap:var(--wp--preset--spacing--50)}
.br-post-card{background:var(--wp--preset--color--clair);border-radius:var(--wp--custom--rayon--moyen);overflow:hidden;height:100%}
.br-post-card .wp-block-post-featured-image{margin:0}
.br-post-card:not(:has(.wp-block-post-featured-image))::before{content:"";display:block;aspect-ratio:4/3;background:radial-gradient(ellipse 40% 34% at 62% 48%,var(--br-shape) 98%,transparent 100%),radial-gradient(ellipse 22% 18% at 36% 62%,var(--br-shape2) 98%,transparent 100%),var(--br-bg)}
.wp-block-post-template>li:nth-child(3n+1) .br-post-card{--br-bg:var(--wp--preset--color--surface);--br-shape:var(--wp--preset--color--deco);--br-shape2:var(--wp--preset--color--secondaire)}
.wp-block-post-template>li:nth-child(3n+2) .br-post-card{--br-bg:var(--wp--preset--color--nuance);--br-shape:var(--wp--preset--color--secondaire);--br-shape2:var(--wp--preset--color--fond)}
.wp-block-post-template>li:nth-child(3n) .br-post-card{--br-bg:var(--wp--preset--color--secondaire);--br-shape:var(--wp--preset--color--surface);--br-shape2:var(--wp--preset--color--deco)}
.br-post-body{padding:1.5rem 1.75rem 2rem}
.br-post-body>*{margin:0}
.br-post-body .wp-block-post-title{font-size:1.4rem;line-height:1.25;margin:.5rem 0 1rem}
.br-post-body .wp-block-post-title a{text-decoration:none;color:inherit}
.br-post-body .wp-block-post-title a:hover{color:var(--wp--preset--color--accent)}
.br-post-body .wp-block-post-terms a{color:inherit;text-decoration:none;font-size:.9rem}
.br-header{padding-top:1.4rem;padding-bottom:1.4rem}
.br-header-inner{max-width:var(--wp--style--global--content-size);margin-left:auto!important;margin-right:auto!important;width:100%}
.br-logo{font-family:var(--wp--preset--font-family--titres);font-size:1.9rem;font-weight:700;letter-spacing:-.04em;line-height:1;margin:0}
.br-logo a,.br-logo{text-decoration:none;color:inherit;position:relative}
.br-logo a::after,.wp-block-site-title.br-logo a::after{content:"";display:inline-block;width:.42em;height:.3em;margin-left:.08em;background:var(--wp--preset--color--deco);border-radius:var(--wp--custom--forme--blob);transform:rotate(-14deg)}
.br-nav{gap:1.5rem;font-size:.95rem}
.br-nav a{text-decoration:none}
.br-nav a:hover{color:var(--wp--preset--color--accent)}
.wp-block-navigation__responsive-container.is-menu-open{background:var(--wp--preset--color--fond)!important;padding:2rem}
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content{font-family:var(--wp--preset--font-family--titres);font-size:2.2rem;font-weight:600;gap:1rem}
.br-footer{padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--40)}
.br-footer a{color:inherit}
.br-footer-mail{font-family:var(--wp--preset--font-family--titres);font-size:clamp(1.8rem,4.6vw,3.6rem);font-weight:600;letter-spacing:-.03em;line-height:1.05;margin-bottom:var(--wp--preset--spacing--60)!important;word-break:break-word}
.br-footer-mail a{text-decoration:none;background-image:linear-gradient(var(--wp--preset--color--deco),var(--wp--preset--color--deco));background-size:100% 4px;background-position:0 100%;background-repeat:no-repeat;padding-bottom:.1em}
.br-footer-mail a:hover{color:var(--wp--preset--color--surface)}
.br-footer-text{opacity:.75;max-width:26em}
.br-footer .br-label{color:var(--wp--preset--color--surface)}
.br-footer-bottom{border-top:1px solid color-mix(in srgb,currentColor 18%,transparent);padding-top:1.5rem;margin-top:var(--wp--preset--spacing--60)!important;font-size:.9rem;opacity:.75}
.br-footer-bottom p{margin:0}
.wp-block-button.is-style-outline .wp-block-button__link{background:transparent;color:var(--wp--preset--color--texte);border:1.5px solid currentColor;padding:calc(1rem - 1.5px) calc(1.8rem - 1.5px)}
.wp-block-button.is-style-outline .wp-block-button__link:hover{background:var(--wp--preset--color--texte);color:var(--wp--preset--color--fond);border-color:var(--wp--preset--color--texte)}
.wp-block-details{border-bottom:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent);padding:1.2rem 0}
.wp-block-details summary{font-weight:600;cursor:pointer}
.br-article .wp-block-post-content>h2{font-size:var(--wp--preset--font-size--x-large);margin-top:2.5rem}
:where(.wp-site-blocks) :focus-visible{outline:2px solid var(--wp--preset--color--accent);outline-offset:3px}
@media (max-width:781px){
.br-section{padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)}
.br-split{gap:var(--wp--preset--spacing--50)}
.br-projects+.br-projects{margin-top:var(--wp--preset--spacing--50)!important}
.br-hero .wp-block-column:last-child{max-width:72%;margin:0 auto}
.br-intro{padding-top:var(--wp--preset--spacing--40)}
.br-cta::before{width:240px;height:170px;right:-80px;top:-60px}
.br-cta::after{display:none}
.br-stats{display:grid!important;grid-template-columns:1fr 1fr;gap:1.75rem}
.br-meta{display:grid!important;grid-template-columns:1fr 1fr;gap:1.25rem}
.wp-block-image.is-style-br-arrondi img,.br-project .wp-block-image{border-radius:var(--wp--custom--rayon--moyen)}
.br-card{padding:2rem 1.5rem}
.br-logo{font-size:1.6rem}
}
.br-logo-sub{font-weight:500;color:var(--wp--preset--color--texte-doux)}
.br-footer .br-logo-sub{color:var(--wp--preset--color--surface)}
.br-logo a::after,.wp-block-site-title.br-logo a::after{order:2}
.br-breadcrumb{font-size:.875rem;color:var(--wp--preset--color--texte-doux);margin-bottom:1.5rem}
.br-breadcrumb a{color:inherit}
.br-intro{font-size:var(--wp--preset--font-size--large);line-height:1.55;font-weight:500}
.br-table table{border-collapse:collapse;width:100%;font-size:.98rem}
.br-table th{text-align:left;font-weight:600;font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;color:var(--wp--preset--color--texte-doux);border-bottom:2px solid var(--wp--preset--color--texte);padding:.75rem .9rem .75rem 0}
.br-table td{border-bottom:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 16%,transparent);padding:1rem .9rem 1rem 0;vertical-align:top}
.br-table td:first-child{font-weight:600}
.br-table a{color:var(--wp--preset--color--texte);text-decoration-color:var(--wp--preset--color--deco);text-underline-offset:3px}
.br-planning td:last-child a{display:inline-block;font-weight:600;font-size:.9rem;text-decoration:none;border:1.5px solid var(--wp--preset--color--texte);border-radius:var(--wp--custom--rayon--bouton);padding:.35rem 1rem}
.br-planning td:last-child a:hover{background:var(--wp--preset--color--texte);color:var(--wp--preset--color--fond)}
.br-planning td:last-child{text-align:right}
.br-style+.br-style{margin-top:0}
.br-style h3{font-size:var(--wp--preset--font-size--x-large);scroll-margin-top:2rem}
.br-price{display:flex;flex-direction:column}
.br-price .wp-block-buttons{margin-top:auto;padding-top:1rem}
.br-price h3{margin:0}
.br-booking{padding:2.5rem}
.br-booking .br-chips{margin:1.5rem 0 0}
.br-steps-list li{margin:.5rem 0}
.br-sticky{display:none}
.br-card .br-stat{color:var(--wp--preset--color--secondaire)}
.br-section .br-card{height:100%}
.br-article .br-label a{color:inherit;text-decoration:none}
.br-skip:focus{position:fixed;top:1rem;left:1rem;z-index:100;background:var(--wp--preset--color--texte);color:var(--wp--preset--color--fond);padding:.75rem 1rem;border-radius:var(--wp--custom--rayon--petit)}
@media (max-width:781px){
.br-sticky{display:block;position:fixed;left:0;right:0;bottom:0;z-index:50;padding:.75rem 1rem calc(.75rem + env(safe-area-inset-bottom));background:var(--wp--preset--color--fond);box-shadow:0 -10px 30px -12px color-mix(in srgb,var(--wp--preset--color--texte) 35%,transparent)}
.br-sticky .wp-block-buttons,.br-sticky .wp-block-button,.br-sticky .wp-block-button__link{width:100%;justify-content:center;text-align:center}
.br-footer{padding-bottom:6rem}
.br-table{overflow-x:auto}
.br-table table{font-size:.92rem}
.br-planning td:last-child a{padding:.3rem .75rem}
.br-nav{gap:1rem}
}

.br-header-cta{margin:0}
.br-header-cta .wp-block-button__link{padding:.6rem 1.3rem;font-size:.95rem;white-space:nowrap}
.br-header-cta,.br-header-actions{flex-shrink:0}
.br-header-right{gap:1.5rem}
@media (max-width:781px){.wp-block-buttons.br-header-cta{display:none}}

/* Sections : hero bannière */
.br-banniere{color:var(--wp--preset--color--fond);padding:var(--wp--preset--spacing--70) var(--wp--style--root--padding-right,1.5rem) var(--wp--preset--spacing--70) var(--wp--style--root--padding-left,1.5rem)!important}
.br-banniere .wp-block-cover__background:not(.has-background-dim-70):not(.has-background-dim-80):not(.has-background-dim-90):not(.has-background-dim-100){opacity:.7!important}
.br-banniere .wp-block-cover__inner-container{color:inherit}
.br-banniere-inner{max-width:44rem}
.br-banniere h1,.br-banniere .br-label,.br-banniere .br-lead{color:inherit}
.br-banniere .br-lead{opacity:1}
.br-banniere .wp-block-button.is-style-outline .wp-block-button__link{color:var(--wp--preset--color--fond);border-color:currentColor}
.br-banniere .wp-block-button.is-style-outline .wp-block-button__link:hover{background:var(--wp--preset--color--fond);color:var(--wp--preset--color--texte)}
.br-banniere .wp-block-button:not(.is-style-outline) .wp-block-button__link{background:var(--wp--preset--color--fond);color:var(--wp--preset--color--texte)}
.br-banniere .wp-block-button:not(.is-style-outline) .wp-block-button__link:hover{background:var(--wp--preset--color--accent);color:var(--wp--preset--color--fond)}
@media (max-width:781px){.br-banniere{min-height:74svh!important}}
/* Sections : offre */
@media (max-width:781px){.br-alterne{flex-direction:column-reverse}}
.br-split+.br-split{margin-top:var(--wp--preset--spacing--70)!important}
.br-prices{align-items:stretch}
.br-price--vedette{box-shadow:0 0 0 2px var(--wp--preset--color--accent)}
.br-price .br-chip{align-self:flex-start;background:var(--wp--preset--color--accent);color:var(--wp--preset--color--fond);margin-bottom:1rem!important}
.br-price .br-stat{margin:.6rem 0 .4rem;font-size:clamp(2.4rem,4vw,3.2rem)}
/* Sections : confiance */
.br-stats-row{gap:var(--wp--preset--spacing--50)}
.br-stats-row .br-stat{font-size:clamp(2.4rem,4.4vw,3.6rem)}
.br-stats-row p.br-muted{margin:0}
.br-avis .wp-block-quote{border:0;padding:0;margin:0}
.br-avis .wp-block-quote p{font-size:var(--wp--preset--font-size--large);line-height:1.5}
.br-avis .wp-block-quote cite{display:block;margin-top:1.25rem;font-style:normal;font-weight:600;font-size:.9rem;color:var(--wp--preset--color--texte-doux)}
.br-logos{gap:2rem 3rem!important;align-items:center;margin-top:1.5rem!important}
.br-logos figure{margin:0}
.br-logos img{height:52px;width:auto;opacity:.85;filter:grayscale(1)}
.br-avap{position:relative}
.br-avap figure{margin:0}
.br-avap .br-avap-tag{position:absolute;top:1rem;left:1rem;background:var(--wp--preset--color--sombre);color:var(--wp--preset--color--fond)}
.wp-block-gallery.br-mosaique{display:grid!important;grid-template-columns:repeat(3,1fr);grid-auto-rows:clamp(140px,18vw,240px);gap:1rem!important}
.wp-block-gallery.br-mosaique figure.wp-block-image{width:auto!important;margin:0!important;height:100%}
.wp-block-gallery.br-mosaique figure.wp-block-image img{height:100%!important;width:100%!important;object-fit:cover;border-radius:var(--wp--custom--rayon--moyen)}
.wp-block-gallery.br-mosaique figure:nth-child(1){grid-row:span 2;grid-column:span 2}
@media (max-width:781px){.wp-block-gallery.br-mosaique{grid-template-columns:1fr 1fr}.wp-block-gallery.br-mosaique figure:nth-child(1){grid-column:span 2;grid-row:span 1}}
/* Sections : contact */
.br-zone{list-style:none;padding:0;display:flex;flex-wrap:wrap;gap:.5rem;margin:1.5rem 0}
.br-zone .br-chip{font-size:.95rem;padding:.65rem 1.1rem}
.br-a-remplacer{border:2px dashed var(--wp--preset--color--texte-doux);padding:1rem 1.25rem;border-radius:var(--wp--custom--rayon--petit);color:var(--wp--preset--color--texte-doux)}
.br-contact-rapide{margin-top:1rem;gap:.75rem}
.br-card .br-horaires{margin-top:1rem}

.br-banniere .wp-block-cover__inner-container{width:100%!important;max-width:var(--wp--style--global--content-size);margin-left:auto!important;margin-right:auto!important}
.br-banniere .wp-block-cover__inner-container>.br-banniere-inner{margin-left:0!important}
.br-table table,.br-table th,.br-table td{border-left:0;border-right:0;border-top:0}
.br-table table{border:0}
.br-table th:first-child,.br-table td:first-child{padding-left:0}
.br-section-head{margin-bottom:var(--wp--preset--spacing--50)!important}

/* Pages légales */
.br-legal>*,.br-mentions>*{max-width:46rem}
.br-legal h2,.br-mentions h2{font-size:var(--wp--preset--font-size--x-large);margin-top:var(--wp--preset--spacing--60)}
.br-legal>:first-child,.br-mentions>h2:first-child{margin-top:0}

/* Sous-menus */
.br-nav .wp-block-navigation__submenu-container{background:var(--wp--preset--color--clair)!important;color:var(--wp--preset--color--texte)!important;border:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 12%,transparent)!important;border-radius:var(--wp--custom--rayon--petit);padding:.4rem!important;min-width:230px!important;box-shadow:0 12px 30px -16px color-mix(in srgb,var(--wp--preset--color--texte) 45%,transparent)}
.br-nav .wp-block-navigation__submenu-container .wp-block-navigation-item__content{padding:.55rem .8rem!important;border-radius:var(--wp--custom--rayon--petit)}
.br-nav .wp-block-navigation__submenu-container .wp-block-navigation-item__content:hover{background:var(--wp--preset--color--fond)}

/* Page d'atterrissage */
.br-header-actions{gap:.5rem;flex-wrap:nowrap}
@media (max-width:781px){.br-header-actions .br-header-cta-btn{display:none}.br-header-tel .wp-block-button__link{padding:.6rem 1rem}}
.br-footer--atterrissage{padding-top:var(--wp--preset--spacing--50)}
.br-footer--atterrissage .br-footer-bottom{margin-top:var(--wp--preset--spacing--40)!important}

/* Pages liées (maillage interne) */
.br-liees{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(15rem,1fr));gap:var(--wp--preset--spacing--40)}
.br-liee{position:relative;background:var(--wp--preset--color--clair);border-radius:var(--wp--custom--rayon--moyen);padding:1.5rem 1.75rem;transition:box-shadow .2s}
