.br-formulaire-ff .ff-btn-submit:focus-visible{outline:3px solid var(--wp--preset--color--texte);outline-offset:3px}
.br-formulaire-ff .ff-message-success{border:0;border-left:4px solid var(--wp--preset--color--accent);background:var(--wp--preset--color--surface);color:var(--wp--preset--color--texte);padding:1rem 1.25rem;box-shadow:none}
.br-formulaire-ff .ff-errors-in-stack{color:#b32d2e}
